  "1a56wwy": "आपका खाता सत्यापित नहीं हो सका। लॉग आउट करके फिर लॉग इन करें; फिर भी विफल हो तो साइट मालिक को नया firebase-rules.json (\"recovery\" खंड) Firebase में चिपकाकर Publish दबाना होगा।",
