  "18t22yg": "रिकवरी Gmail",
  "1xakj79": "केवल तभी काम करता है जब खाते में रिकवरी Gmail हो (प्रोफ़ाइल › सेटिंग्स)। Google खाते: “Google से साइन इन करें” का उपयोग करें।",
  "1yx8hnw": "पासवर्ड रीसेट हो गया। नए पासवर्ड से लॉग इन करें।",
  "1ch5cq9": "कोड के सभी 6 अंक दर्ज करें",
  "1tkkukf": "कोड की समय-सीमा खत्म हो गई या बहुत बार गलत डाला गया। नया कोड पाने के लिए \"कोड फिर भेजें\" दबाएँ।",
  "1qu0e8h": "गलत कोड",
  "uc1kty": "इस खाते में रिकवरी Gmail नहीं है, इसलिए कोड नहीं भेजा जा सकता। कृपया किसी एडमिन से मदद लें।",
  "z9bb47": "इस उपयोगकर्ता नाम वाला कोई खाता नहीं",
  "1djyy2p": "यह खाता Google साइन-इन का उपयोग करता है। \"Google से साइन इन करें\" दबाएँ।",
  "lvsl0m": "अभी-अभी कोड भेजा गया। एक मिनट रुककर फिर कोशिश करें।",
  "td9r40": "सर्वर ने आज का ईमेल कोटा खत्म कर दिया। कृपया कल फिर कोशिश करें।",
  "e2tdbs": "अमान्य ईमेल पता",
  "1xzszo5": "साइट मालिक ने ईमेल सर्वर सक्षम नहीं किया है (config.js में mailApi, README देखें)।",
  "l5u3wz": "पासवर्ड रिकवर करने और Gmail सूचनाएँ पाने के लिए",
  "h9nnhb": "सत्यापन कोड भेजें",
  "18tbqwf": "पुष्टि करें",
