  "17rv3f8": "जोड़ें",
  "18wuq59": "बदलें",
  "vhdmo0": "कोई नहीं – पासवर्ड रिकवर करने के लिए एक जोड़ें",
  "phj7wc": "रिकवरी Gmail हटा दिया गया",
  "40ubi2": "रिकवरी Gmail हटाएँ? इसके बाद आप ईमेल से पासवर्ड रिकवर नहीं कर पाएँगे और Gmail सूचनाएँ नहीं मिलेंगी।",
  "1cmtult": "ईमेल से सूचनाएँ पाने के लिए रिकवरी Gmail (नीचे) जोड़ें।",
  "1hbb1vr": "Gmail सूचनाएँ चालू रखने वाले खिलाड़ियों को ईमेल भी करें (Apps Script 5 मिनट में भेजता है)",
  "5989r1": "घोषणा प्रकाशित। Gmail सूचनाएँ चालू रखने वाले खिलाड़ियों को 5 मिनट में ईमेल जाएँगे।",
  "11q3s6m": "पासवर्ड बदलें",
