  "1fbj1yp": "नया पासवर्ड दोबारा लिखें",
  "6mfy63": "आपका मौजूदा पासवर्ड गलत है",
  "1yp44ma": "नया पासवर्ड मौजूदा से अलग होना चाहिए",
  "1safkf0": "Google खातों का यहाँ अलग पासवर्ड नहीं होता। इसे अपने Google खाते में बदलें।",
  "wb6pai": "अपना मौजूदा पासवर्ड डालें",
  "1q7ilg0": "बदला जा रहा है…",
  "466mdo": "पासवर्ड बदल गया",
