  "1pq7eqd": "ब्राउज़र ने Google साइन-इन विंडो रोक दी। फिर से \"Google से साइन इन करें\" पर टैप करें (या ब्राउज़र सेटिंग्स में पॉप-अप की अनुमति दें)।",
  "t6t2uv": "Google, Zalo / Facebook / Messenger… ब्राउज़र के अंदर साइन-इन की अनुमति नहीं देता। साइट को Chrome या Safari में खोलें (नीचे देखें)।",
  "b13kcb": "ब्राउज़र साइट स्टोरेज रोक रहा है (प्राइवेट मोड या कुकी ब्लॉक)। उसे बंद करके फिर कोशिश करें।",
  "1rmo0aa": "ब्राउज़र ने Google साइन-इन का परिणाम खो दिया। फिर कोशिश करें; बार-बार विफल हो तो साइट मालिक साइट को Firebase Hosting पर होस्ट करे (README देखें)।",
  "nl2gsn": "Google साइन-इन विफल, कृपया बाद में कोशिश करें।",
  "1clu72n": "खेल खत्म",
