  "1vzv6d7": "संदेश नहीं गया: कनेक्शन टूट गया।",
  "1vfvucw": "आपने पहले ही ड्रॉ का प्रस्ताव दिया है, प्रतिद्वंद्वी की प्रतीक्षा है।",
  "q3vuc0": "अपने ही खाते के विरुद्ध गेम रैंक या Elo में नहीं गिना जाता",
  "1a8ifm5": "ज्ञान लाइब्रेरी खोजें",
