  "186g6gd": "कंप्यूटर या ऑनलाइन कुछ गेम खेलें: Stockfish 19 हर चाल जाँचता है और सहायक आपकी कमज़ोरियाँ खोजता है। तब तक, यह आपके कोर्स की प्रगति पर आधारित योजना है।",
  "10lxd8f": "रानी की अदला-बदली",
  "1dg0wfo": "रानी का बलिदान",
  "4el6o6": "नाम",
  "1p6iil1": "आख़िरी बार सक्रिय",
