  "15vemej": "शहमात चूकना",
  "d2ex46": "कमज़ोर ओपनिंग",
  "1x4l74b": "असुरक्षित राजा",
  "v8hp7j": "बिना योजना का मिडलगेम",
  "a4z0qg": "गेम खत्म करना / एंडगेम",
  "rxiob": "हर चाल से पहले पूछें: “मेरे प्रतिद्वंद्वी ने अभी क्या धमकी दी? इस चाल के बाद मेरा कौन-सा मोहरा असुरक्षित है?”",
  "1iwpe2z": "हर बारी में पहले शह, कब्ज़ा और धमकियाँ देखें: जीत का वार आमतौर पर वहीं होता है।",
  "qrpsfi": "मात के पैटर्न सीखें (पिछली पंक्ति, अरेबियन, बोडेन, स्मदर्ड…) ताकि गेम में उन्हें देख सकें।",
  "xhwanc": "केंद्र पर कब्ज़ा करें, पहले घोड़े और ऊँट निकालें, जल्दी कैसलिंग करें, और बिना ज़रूरत एक मोहरा दो बार न चलें।",
  "1ulggiy": "10वीं चाल से पहले कैसलिंग करें और प्यादों से राजा की रक्षा रखें; जब दुश्मन का राजा बीच में ही हो, केंद्र खोलकर हमला करें।",
  "1t15fl6": "जब कोई युक्ति न हो: अपना सबसे कमज़ोर मोहरा ढूँढें, उसे बेहतर खाने पर लाएँ, और खुली फ़ाइलों पर हाथी जमाएँ।",
  "1fs9wy0": "सामग्री में आगे हों तो: मोहरे बदलें, राजा को आगे लाएँ और पास्ड प्यादा बढ़ाएँ। जल्दबाज़ी न करें: हर चाल जाँचें ताकि गतिरोध न हो।",
  "7xpp3j": "1.e4 का जवाब 1...e5 से दें (ओपन गेम)",
  "lyjqqq": "इकाई पूरी हुई, पक्का करने के लिए दोहराएँ",
  "rj80ha": "कोई गेम विश्लेषित नहीं हो सका (क्या दूसरा गेम विश्लेषित हो रहा है?)",
  "aalaql": "विश्लेषण न हुए गेम का विश्लेषण करें",
  "10pp4mk": "ऊपर।",
  "wrfgt2": ", बेहतर चाल थी",
  "1be8t4g": "आज के लिए लगभग 20 मिनट की योजना:",
  "4s8vwe": "सफ़ेद से:",
  "vr20t": "1.e4 के विरुद्ध काले से:",
  "14vtojm": "1.d4 के विरुद्ध काले से:",
  "1kzm3jo": "जो ओपनिंग आप अभी सबसे खराब खेलते हैं:",
  "1btgvys": "आप सबसे अच्छा जिस चरण में खेलते हैं वह है",
  "1pt5m6n": "इनमें आपको शायद ही दिक्कत होती है:",
  "16dg98h": "मैं प्रश्न समझ नहीं पाया और ज्ञान लाइब्रेरी में मेल खाता लेख नहीं मिला। नीचे का कोई सुझाव या छोटा कीवर्ड आज़माएँ (जैसे: पिन, पास्ड प्यादा, लुसेना)।",
  "hwnfby": "सर्वर व्यस्त है, कृपया कुछ मिनट बाद कोशिश करें।",
  "1b2hmqy": "सहायक के सर्वर से नहीं जुड़ सके।",
  "1d5b5ty": "सर्वर व्यस्त है, फिर कोशिश हो रही है…",
  "rq1kpk": "मुझे जवाब नहीं सूझा, कृपया दूसरे तरीके से पूछें।",
  "15d632n": "सहायक के सर्वर में त्रुटि हुई।",
  "gqs80q": "Stockfish 19 गेम का विश्लेषण कर रहा है",
  "uemrrc": "कंप्यूटर या ऑनलाइन कुछ गेम खेलें: Stockfish 19 हर चाल जाँचता है, और सहायक आपकी कमज़ोरियाँ ढूँढकर आपके लिए योजना बनाता है।",
  "1f3rsx8": "अपनी आम ओपनिंग और हर एक में अपना स्कोर देखने के लिए शुरुआती स्थिति से कुछ गेम खेलें।",
  "11u3lth": "आपके इतिहास में अभी कोई गेम नहीं। कंप्यूटर या ऑनलाइन एक गेम खेलें, यह सहायक की समीक्षा के लिए यहाँ दिखेगा।",
  "o4mziy": "मेरे नवीनतम गेम की समीक्षा करें",
  "1hki4wt": "मेरे खेल की सबसे बड़ी कमज़ोरी क्या है और इसे कैसे सुधारूँ?",
  "19ki7l6": "आज लगभग 30 मिनट में मुझे क्या अभ्यास करना चाहिए?",
  "3eh4u9": "बोर्ड की स्थिति का मेरे लिए विश्लेषण करें",
  "1tnlvlj": "मेरे स्तर पर कौन-सी ओपनिंग खेलनी चाहिए?",
  "tuu2bl": "नमस्ते, आज मैं आपकी क्या मदद कर सकता हूँ?",
  "jcj48p": "उत्तर देने से पहले मैं आपके गेम पढ़ता हूँ, हर लाइन Stockfish 19 से जाँचता हूँ और ज्ञान लाइब्रेरी में खोजता हूँ।",
  "l620kc": "मैं Stockfish 19 से विश्लेषित गेम पढ़कर कमज़ोरियाँ ढूँढता हूँ और अध्ययन योजना सुझाता हूँ। ज्ञान लाइब्रेरी खोजने के लिए कोई अवधारणा (पिन, लुसेना, सिसिलियन…) लिखें।",
  "gw7a17": "सबसे ज़्यादा क्या सुधारें:",
  "w3y60w": "कुछ गेम खेलें ताकि सहायक आपकी कमज़ोरियाँ ढूँढकर योजना बना सके।",
