  "1rsz60j": "{0} के रूप में",
  "1whuabj": "{0}। बेहतर था {1}।",
  "17q4hb2": "दोनों पक्षों ने चाल {0} पर रानियाँ बदलीं: बोर्ड पर कम मोहरे होने से राजा जल्दी लड़ाई में शामिल हो सकता है।",
  "t5n6eb": "आपने चाल {0} पर रानी का बलिदान देकर मात दी। सुंदर अंत!",
  "yhdlku": "प्रतिद्वंद्वी ने चाल {0} पर रानी का बलिदान देकर मात दी: जब आपका राजा घिरा हो, तो प्रतिद्वंद्वी की बलिदान वाली शहें हमेशा जाँचें।",
  "2s2j5x": "अंत में {0} सामग्री में {1} अंक आगे था ({2}–{3})।",
  "fy0vf": "सामग्री में {0} अंक पीछे होने के बावजूद ({1}–{2}), {3} ने फिर भी मात दी: मोहरों की सक्रियता और राजा की सुरक्षा सामग्री से ज़्यादा मायने रखती है।",
  "1cbb1io": "ध्यान देने योग्य: {0} ने रानी से एक छोटा मोहरा लिया,",
  "11dgwg2": "(चाल {0}) और रानी तुरंत वापस ले ली गई, लगभग {1} अंक की सामग्री गई।",
  "cshz0d": "(चाल {0}) {1} का आदान-प्रदान खराब था: पकड़ने वाला मोहरा तुरंत वापस ले लिया गया, लगभग {2} अंक की सामग्री गई।",
  "7no57s": "आप यह साइट इसके ब्राउज़र में खोल रहे हैं:",
  "1f5rl9g": "और Google यहाँ साइन-इन की अनुमति नहीं देता। टैप करें",
  "kjfrhy": "स्क्रीन के कोने में ›",
